document.addEventListener("DOMContentLoaded",()=>{console.log("Class 9 Notes JS Loaded"),initClass9NotesScrollAnimations()});function initClass9NotesScrollAnimations(){const e=new IntersectionObserver(s=>{s.forEach(o=>{o.isIntersecting&&o.target.classList.add("active")})},{threshold:.1});document.querySelectorAll(".note-section, .accordion-item, .quiz-container, .card, .interactive-box").forEach(s=>{s.classList.add("reveal"),e.observe(s)})}function toggleAccordion(e){e.classList.toggle("active");const c=e.nextElementSibling,s=e.querySelector(".fa-chevron-down, .fa-chevron-up");c.classList.contains("open")?(c.classList.remove("open"),s.classList.remove("fa-chevron-up"),s.classList.add("fa-chevron-down")):(c.classList.add("open"),s.classList.remove("fa-chevron-down"),s.classList.add("fa-chevron-up"))}function checkQuiz(e,c){const o=e.parentElement.querySelectorAll(".quiz-option");o.forEach(t=>t.style.pointerEvents="none"),c?(e.classList.add("correct","pop"),e.innerHTML+=' <i class="fas fa-check-circle"></i>'):(e.classList.add("wrong","shake"),e.innerHTML+=' <i class="fas fa-times-circle"></i>',setTimeout(()=>{const t=Array.from(o).find(n=>n.getAttribute("onclick")?.includes("true"));t&&(t.classList.add("correct","pop"),t.innerHTML+=' <i class="fas fa-check-circle"></i>')},500))}
